def set_left_most_unset_bit(n: int) -> int:
    """
    Return the integer obtained by setting the leftmost unset bit of n.
    The bit width considered is the number of bits needed to represent n,
    excluding leading zeros. If all bits are set, n is returned unchanged.
    """
    if n == 0:
        return 1

    if n < 0:
        return -set_left_most_unset_bit(-n)

    all_bits_set = (1 << n.bit_length()) - 1
    unset_bits = (~n) & all_bits_set

    if unset_bits == 0:
        return n

    leftmost_unset_mask = 1 << (unset_bits.bit_length() - 1)
    return n | leftmost_unset_mask


