from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Process events by time. At the same timestamp, offline status changes
        # must be applied before message events.
        events.sort(key=lambda event: (int(event[1]), 0 if event[0] == "OFFLINE" else 1))

        mentions = [0] * numberOfUsers
        offline_at = [-1] * numberOfUsers

        def is_online(user_id: int, timestamp: int) -> bool:
            return offline_at[user_id] == -1 or timestamp >= offline_at[user_id] + 60

        for event_type, timestamp_str, data in events:
            timestamp = int(timestamp_str)

            if event_type == "OFFLINE":
                user_id = int(data)
                offline_at[user_id] = timestamp
            else:
                for token in data.split():
                    if token == "ALL":
                        for user_id in range(numberOfUsers):
                            mentions[user_id] += 1
                    elif token == "HERE":
                        for user_id in range(numberOfUsers):
                            if is_online(user_id, timestamp):
                                mentions[user_id] += 1
                    else:
                        # token is of the form "id<number>"
                        user_id = int(token[2:])
                        mentions[user_id] += 1

        return mentions
