from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups:
            return []

        max_group = max(groups)
        assigned_by_value = [-1] * (max_group + 1)
        seen = [False] * (max_group + 1)

        for index, value in enumerate(elements):
            if value > max_group or seen[value]:
                continue

            seen[value] = True

            for multiple in range(value, max_group + 1, value):
                if assigned_by_value[multiple] == -1:
                    assigned_by_value[multiple] = index

        return [assigned_by_value[g] for g in groups]
