class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        take = True

        for i, row in enumerate(grid):
            if i % 2 == 0:
                col_range = range(len(row))
            else:
                col_range = range(len(row) - 1, -1, -1)

            for j in col_range:
                if take:
                    result.append(grid[i][j])
                take = not take

        return result
